<?php
require_once __DIR__.'/../includes/functions.php';require_role('teacher','admin');
if(current_user()['role']==='teacher'){$q=db()->prepare('SELECT h.*,u.name,s.roll_number,sub.subject_name,e.exam_name FROM result_history h JOIN users u ON u.user_id=h.user_id JOIN students s ON s.student_id=h.student_id JOIN subjects sub ON sub.subject_id=h.subject_id JOIN exams e ON e.exam_id=h.exam_id WHERE h.user_id=? ORDER BY h.changed_at DESC');$q->execute([current_user()['user_id']]);}else{$q=db()->query('SELECT h.*,u.name,s.roll_number,sub.subject_name,e.exam_name FROM result_history h JOIN users u ON u.user_id=h.user_id JOIN students s ON s.student_id=h.student_id JOIN subjects sub ON sub.subject_id=h.subject_id JOIN exams e ON e.exam_id=h.exam_id ORDER BY h.changed_at DESC');}$rows=$q->fetchAll();include __DIR__.'/../includes/header.php';?>
<div class="card"><div class="card-header">Result modification history</div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Date / time</th><th>Changed by</th><th>Student</th><th>Subject / exam</th><th>Old marks</th><th>New marks</th><th>Reason</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['changed_at'])?></td><td><?=e($r['name'])?></td><td><?=e($r['roll_number'])?></td><td><?=e($r['subject_name'].' / '.$r['exam_name'])?></td><td><?=e((string)($r['old_marks']??'—'))?></td><td><?=e((string)$r['new_marks'])?></td><td><?=e($r['reason']??'')?></td></tr><?php endforeach;?></tbody></table></div></div>
<?php include __DIR__.'/../includes/footer.php';?>